from __future__ import annotations

def successor_witness(n: int) -> dict[int, int]:
    if n < 0:
        raise ValueError("n must be nonnegative")
    return {i: i for i in range(n)}

for n in range(1, 9):
    injection = successor_witness(n)
    assert len(set(injection.values())) == n
    print(f"{n} points inject into {n+1}; the reverse direction is blocked by pigeonhole.")

